"""Attachment files on the local disk (a Docker volume in production)."""

import asyncio
import logging
import secrets
import shutil
from pathlib import Path
from typing import BinaryIO

from app.core.config import settings

logger = logging.getLogger(__name__)


def _root() -> Path:
    return Path(settings.upload_dir).resolve()


def path_for(storage_key: str) -> Path:
    # Keys are generated by us (hex), so they can't escape the upload directory.
    return _root() / storage_key[:2] / storage_key


def new_key() -> str:
    return secrets.token_hex(16)


async def save(storage_key: str, source: BinaryIO) -> None:
    def copy() -> None:
        path = path_for(storage_key)
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("wb") as target:
            shutil.copyfileobj(source, target)

    await asyncio.to_thread(copy)


def remove_files(storage_keys: list[str]) -> None:
    for key in storage_keys:
        try:
            path_for(key).unlink(missing_ok=True)
        except OSError:
            logger.exception("Could not delete attachment file %s", key)
